// app.js — juego táctil “Toca el punto”
'use strict';
(function () {
  const cv = document.getElementById("game");
  const c = cv.getContext("2d");
  let score = 0, timeLeft = 30, playing = false, timer = null;
  const dot = { x: 160, y: 210, r: 26 };
  let best = 0;
  try { best = Number(localStorage.getItem("tapgame.best") || 0); } catch (e) {}
  document.getElementById("best").textContent = best;

  function resize() {
    const r = cv.getBoundingClientRect();
    cv.width = Math.round(r.width * (window.devicePixelRatio || 1));
    cv.height = Math.round(r.height * (window.devicePixelRatio || 1));
    draw();
  }
  window.addEventListener("resize", resize);

  function place() {
    const m = dot.r + 6;
    dot.x = m + Math.random() * (cv.width - 2 * m);
    dot.y = m + Math.random() * (cv.height - 2 * m);
    dot.r = Math.max(12, 26 - score * 0.4);
  }

  function draw() {
    c.clearRect(0, 0, cv.width, cv.height);
    if (!playing) {
      c.fillStyle = "#5b6675";
      c.font = "600 18px system-ui, sans-serif";
      c.textAlign = "center";
      c.fillText("Pulsa Jugar", cv.width / 2, cv.height / 2);
      return;
    }
    c.beginPath();
    c.arc(dot.x, dot.y, dot.r, 0, Math.PI * 2);
    c.fillStyle = "#e74c3c";
    c.fill();
    c.beginPath();
    c.arc(dot.x, dot.y, dot.r * 0.45, 0, Math.PI * 2);
    c.fillStyle = "#fff";
    c.fill();
  }

  function end() {
    playing = false;
    clearInterval(timer); timer = null;
    document.getElementById("start").textContent = "Jugar otra vez";
    if (score > best) {
      best = score;
      try { localStorage.setItem("tapgame.best", String(best)); } catch (e) {}
      document.getElementById("best").textContent = best;
      document.getElementById("msg").textContent = "¡Nuevo récord: " + best + "!";
    } else {
      document.getElementById("msg").textContent = "Fin: " + score + " puntos. Récord: " + best + ".";
    }
    draw();
  }

  document.getElementById("start").addEventListener("click", function () {
    if (playing) return;
    score = 0; timeLeft = 30; playing = true;
    document.getElementById("score").textContent = 0;
    document.getElementById("time").textContent = 30;
    document.getElementById("msg").textContent = "¡Vamos!";
    place(); draw();
    timer = setInterval(function () {
      timeLeft--;
      document.getElementById("time").textContent = timeLeft;
      if (timeLeft <= 0) end();
    }, 1000);
  });

  /* Entrada táctil: dedo y ratón (pointerdown) */
  cv.addEventListener("pointerdown", function (ev) {
    if (!playing) return;
    const r = cv.getBoundingClientRect();
    const x = (ev.clientX - r.left) * (cv.width / r.width);
    const y = (ev.clientY - r.top) * (cv.height / r.height);
    const dx = x - dot.x, dy = y - dot.y;
    if (dx * dx + dy * dy <= (dot.r + 10) * (dot.r + 10)) {
      score++;
      document.getElementById("score").textContent = score;
      place(); draw();
    }
  });

  resize();
})();

